import * as THREE from './vendor/three.module.js';
export function batchStatic(group){const batches=new Map();for(const o of [...group.children]){if(!o.isMesh||o.isInstancedMesh||o.userData.dynamic||o.material.transparent)continue;let batch=batches.get(o.material);if(!batch){batch=[];batches.set(o.material,batch)}o.updateMatrix();const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(o.matrix);batch.push(geo);o.geometry.dispose();group.remove(o)}for(const [mat,geos] of batches){const length=geos.reduce((n,g)=>n+g.attributes.position.array.length,0),pos=new Float32Array(length),norm=new Float32Array(length),uv=new Float32Array(length/3*2);let at=0;for(const g of geos){pos.set(g.attributes.position.array,at);norm.set(g.attributes.normal.array,at);if(g.attributes.uv)uv.set(g.attributes.uv.array,at/3*2);at+=g.attributes.position.array.length;g.dispose()}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(pos,3));geo.setAttribute('normal',new THREE.BufferAttribute(norm,3));geo.setAttribute('uv',new THREE.BufferAttribute(uv,2));const mesh=new THREE.Mesh(geo,mat);mesh.castShadow=true;mesh.receiveShadow=true;mesh.name='Batched courtyard furniture';group.add(mesh)}}
